using System.Text.Json.Nodes;
using PowerShapeMcp;
internal static class ReturnedSetReconciliationCheck
{
 internal static int Run(string input,string output){var report=JsonNode.Parse(File.ReadAllText(input))!.AsObject();var f=report["fixture"]!.AsObject();string root=f["root"]!.GetValue<string>(),id=f["executionId"]!.GetValue<string>(),sha=f["executionSha256"]!.GetValue<string>();int cases=0;_=ReturnedSetReconciliationProof.Execution(root,id,sha,fixture:true);cases++;
  foreach(string bad in new[]{new string('0',64),new string('a',64)}){bool rejected=false;try{_=ReturnedSetReconciliationProof.Execution(root,id,bad,fixture:true);}catch{rejected=true;}if(!rejected)throw new InvalidOperationException("Wrong archive receipt SHA accepted.");cases++;}
  var x=JsonNode.Parse(File.ReadAllText(Path.Combine(root,"responses",id+".json")))!.AsObject();var p=x["plan"]!.AsObject();var original=p["arguments"]!["executionRequestId"]!.GetValue<string>();string[] paths=[Path.Combine(root,"returnedsetarchives",original+".json"),Path.Combine(root,"returnedsetclaims",original+".json"),Path.Combine(root,"operations",id,"000003.json"),Path.Combine(root,"ownedexecutions",original+".json")];foreach(string path in paths){byte[] before=File.ReadAllBytes(path);try{File.AppendAllText(path," ");bool rejected=false;try{_=ReturnedSetReconciliationProof.Execution(root,id,sha,fixture:true);}catch{rejected=true;}if(!rejected)throw new InvalidOperationException("Tampered source accepted: "+path);cases++;}finally{File.WriteAllBytes(path,before);}}
  var arguments=p["arguments"]!.AsObject();var baseline=ReturnedSurfaceSetProof.ReadOrigin(root,arguments);string copy=p["copyId"]!.GetValue<string>(),fence=Path.Combine(root,"workingcopies",copy,"mutation-fence.json"),fenceSha=p["originalFenceSha256"]!.GetValue<string>();byte[] fenceBytes=File.ReadAllBytes(fence);try{File.Delete(fence);var archived=ReturnedSurfaceSetProof.ReadOrigin(root,arguments,new(original,copy,fenceSha));if(!JsonNode.DeepEquals(archived.Pins,baseline.Pins)||!JsonNode.DeepEquals(archived.SavedBaseline,baseline.SavedBaseline))throw new InvalidOperationException("Explicit archive source changed original logical pin map.");cases++;bool refused=false;try{_=ReturnedSurfaceSetProof.ReadOrigin(root,arguments);}catch{refused=true;}if(!refused)throw new InvalidOperationException("Default observer source admitted missing fence.");cases++;foreach(var wrong in new[]{new ReturnedSurfaceSetProof.ArchivedFence(new string('a',32),copy,fenceSha),new ReturnedSurfaceSetProof.ArchivedFence(original,new string('b',32),fenceSha),new ReturnedSurfaceSetProof.ArchivedFence(original,copy,new string('0',64))}){refused=false;try{_=ReturnedSurfaceSetProof.ReadOrigin(root,arguments,wrong);}catch{refused=true;}if(!refused)throw new InvalidOperationException("Mismatched archive identity admitted.");cases++;}}finally{File.WriteAllBytes(fence,fenceBytes);}
  File.WriteAllText(output,new JsonObject{["state"]="passed",["cases"]=cases,["cadConnectionAttempted"]=false,["liveFenceReleased"]=false}.ToJsonString());Console.WriteLine($"PASS: {cases} independent Framework/SDK returned-set archive/claim/history checks; no CAD.");return 0;}
}
